    r0=min(r for r,c in obj);r1=max(r for r,c in obj);c0=min(c for r,c in obj);c1=max(c for r,c in obj)
    # For each marker outside the central rectangle, extend its rectangle row/column
    # outward to the nearest canvas edge; markers within its row/column are gaps.
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    for r,c in marks:
